test('profile language diagnostic: the identical original failure survives observation schema and log errors',async()=>{
 const api=profileLanguageDiagnosticApi();for(const mode of['observe','schema','log','valid']){const original=Error('original focus failure'),lines:string[]=[];let caught:unknown;try{await api.rethrow(original,async()=>{if(mode==='observe')throw Error('private-canary');return mode==='schema'?{private:'private-canary'}:validProfileLanguageDiagnostic();},line=>{if(mode==='log')throw Error('private-canary');lines.push(line);});}catch(error){caught=error;}expect(caught).toBe(original);expect(original.message).toBe('original focus failure');expect(lines).toHaveLength(mode==='valid'?1:0);if(lines.length)expect(lines[0]).toMatch(/^CUEVO_PROFILE_LANGUAGE_FOCUS_UNVERIFIED /);}
});
test('profile language diagnostic: a stalled post-failure read cannot replace the original error or emit later',async()=>{
 const api=profileLanguageDiagnosticApi(),original=Error('original focus failure'),lines:string[]=[];let settle:((value:unknown)=>void)|undefined,caught:unknown;
 try{await api.rethrow(original,()=>new Promise(resolve=>{settle=resolve;}),line=>lines.push(line));}catch(error){caught=error;}expect(caught).toBe(original);expect(lines).toEqual([]);settle?.(validProfileLanguageDiagnostic());await Promise.resolve();expect(lines).toEqual([]);
});
test('profile language diagnostic: stalled observation and finally cleanup release the identical original error within a finite bound',async()=>{
 const api=profileLanguageDiagnosticApi(),original=Error('original focus failure'),lines:string[]=[],deadline=Symbol('diagnostic deadline');let rejectRead:((error:Error)=>void)|undefined,rejectCleanup:((error:Error)=>void)|undefined,timer:ReturnType<typeof setTimeout>|undefined,result:unknown;
 const body=(async()=>{try{await api.rethrow(original,()=>new Promise((_resolve,reject)=>{rejectRead=reject;}),line=>lines.push(line));}finally{await disposeProfileLanguageFixture({evaluate:()=>new Promise((_resolve,reject)=>{rejectCleanup=reject;})}as unknown as Page);}})(),outcome=body.then(()=>undefined,error=>error);
 try{result=await Promise.race([outcome,new Promise(resolve=>{timer=setTimeout(()=>resolve(deadline),1000);})]);}finally{if(timer)clearTimeout(timer);rejectRead?.(Error('late private read error'));rejectCleanup?.(Error('late private cleanup error'));}
 expect(await outcome).toBe(original);expect(result).toBe(original);expect(lines).toEqual([]);await Promise.resolve();expect(lines).toEqual([]);
});
